    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); comp=[]
                while q:
                    a,b=q.pop(); comp.append((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            x,y=a+dx,b+dy
                            if 0<=x<H and 0<=y<W and g[x][y]!=bg and (x,y) not in seen:
                                seen.add((x,y)); q.append((x,y))
                out.append(comp)
    return out
